def cross(a,b):return [a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]]
def rank(pts):
 if not pts:return -1
 a=[sub(x,pts[0]) for x in pts[1:]];k=0
 for j in range(3):
  pivot=next((i for i in range(k,len(a)) if a[i][j]),None)
